    "tip": "coktan",
    "zorluk": 1,
    "puan": null,
    "baglam": "Gölcük sahilinde deniz suyu sıcaklığı 18 °C ile 19 °C arasında ölçülüyor. Mehmet, bu iki değerin arasındaki bir sıcaklığı bulmak için 18 ile 19'un ortalamasını alıyor.",
    "kok": "Mehmet hangi sayıyı bulur?",
    "secenekler": [
     {
      "metin": "37",
      "dogru": false,
      "hata_turu": "eksik_adim",
      "aciklama": "18 ile 19'u topladın ama ortalama için toplamı 2'ye bölmen gerekiyordu."
     },
     {
      "metin": "1/2",
      "dogru": false,
      "hata_turu": "islem_hatasi",
      "aciklama": "Sayıları çıkardın; ortalamada sayılar toplanır, sonra 2'ye bölünür."
     },
     {
      "metin": "55/2",
      "dogru": false,
      "hata_turu": "islem_hatasi",
      "aciklama": "Yalnız 19'u 2'ye böldün; önce toplamı bulup sonra toplamı 2'ye bölmelisin."
     },
     {
      "metin": "37/2",
      "dogru": true
     }
    ],
    "cevap": "37/2",
    "kabul_edilenler": [
     "18,5"
    ],
    "ipuclari": [
     "Ortalama, iki sayının tam ortasındaki sayıdır.",
     "Ortalama = (birinci sayı + ikinci sayı) ÷ 2.",
     "Önce 18 + 19 toplamını bul; sonra bu toplamı 2'ye bölmeyi unutma."
    ],
    "cozum_adimlari": [
     "1. Ortalama: (18 + 19) ÷ 2.",
     "2. 18 + 19 = 37.",
     "3. 37 ÷ 2 = 37/2 = 18,5.",
     "4. Kontrol: 18 < 18,5 < 19; bulunan sayı iki değerin arasındadır.",
     "5. Cevap: 37/2."
    ],
