      "olcut": "b) Bölümün B'de olmadığını gösterme (3 ÷ 6 = 1/2 ∉ B gibi). x₁, x₂ ∈ B olmak üzere x₁ ÷ x₂ ∉ B olduğunun gösterildiği tüm cevaplar doğrudur.",
      "puan": 3
