    "kok": "a) Hangi öğrencinin önermesinin yanlış olduğunu belirtiniz ve bu önermenin yanlış olduğunu karşıt örnek sunarak gösteriniz. b) Bir önermenin yanlış olduğunu göstermek için tek bir karşıt örneğin neden yeterli olduğunu açıklayınız. (10 puan)",
    "secenekler": null,
    "cevap": "a) Emre'nin önermesi yanlıştır. 1 ∈ ℤ ve 2 ∈ ℤ için 1 ÷ 2 = 1/2 olur ve 1/2 ∉ ℤ'dir. Böylece Emre'nin önermesinin yanlış olduğu karşıt örnek sunularak gösterilmiş olur. b) Önerme, işlemin her iki tam sayı için sonucu tam sayı yaptığını söyler. Bu kurala uymayan tek bir örnek bulunursa “her zaman” iddiası bozulur; bu yüzden tek karşıt örnek yeterlidir.",
    "kabul_edilenler": [],
