    "baglam": "Gölcük'te bir okulun kare biçimli mini futbol sahasının bir kenarı x m'dir. Saha büyütülürken iki komşu kenarı 2'şer m uzatılıyor. Yeni saha, bir kenarı (x + 2) m olan kare oluyor. Yeni saha dört parçaya ayrılıyor. Birinci parça, kenarı x m olan bir kare. İkinci ve üçüncü parça, kenarları x m ve 2 m olan iki dikdörtgen. Dördüncü parça, kenarı 2 m olan bir kare.",
